def solve(s):
    """Return True if s is a valid IPv4 address.
    A valid address consists of exactly four decimal numbers separated by dots.
    Each number must be between 0 and 255 inclusive, contain only digits, and
    must not have leading zeros unless the number is exactly "0".
    """
    parts = s.split('.')
    if len(parts) != 4:
        return False
    for p in parts:
        # each part must be non‑empty and consist only of digits
        if not p or not p.isdigit():
            return False
        # reject leading zeros (e.g., "01") unless the part is exactly "0"
        if len(p) > 1 and p[0] == '0':
            return False
        val = int(p)
        if not (0 <= val <= 255):
            return False
    return True

