def solve(s):
    """Return length of longest substring without repeating characters.
    Sliding window O(n).
    """
    last_index = {}
    start = 0
    max_len = 0
    for i, ch in enumerate(s):
        if ch in last_index and last_index[ch] >= start:
            start = last_index[ch] + 1
        last_index[ch] = i
        max_len = max(max_len, i - start + 1)
    return max_len

def solve(words, width):
    """Greedy word wrap.
    Pack words into lines such that each line (words separated by a single space) does not exceed width.
    If a single word is longer than width, it occupies a line by itself.
    """
    if not words:
        return []
    lines = []
    cur = []
    cur_len = 0  # length of current line without spaces
    for w in words:
        if not cur:
            cur.append(w)
            cur_len = len(w)
        else:
            # check if we can add w with a space
            if cur_len + 1 + len(w) <= width:
                cur.append(w)
                cur_len += 1 + len(w)
            else:
                lines.append(' '.join(cur))
                cur = [w]
                cur_len = len(w)
    if cur:
        lines.append(' '.join(cur))
    return lines

