def solve(lst):
    """Flatten a nested list/tuple of integers into a flat list preserving order.
    The input may be an integer (treated as a single-element list) or a nested
    structure containing integers and further lists/tuples. Non‑list/tuple
    iterables (e.g., strings, sets) are treated as atomic values.
    """
    # If the top‑level object is not a list or tuple, treat it as a single item.
    if not isinstance(lst, (list, tuple)):
        return [lst]
    result = []
    # Use a stack of iterators to avoid recursion limits.
    stack = [iter(lst)]
    while stack:
        try:
            item = next(stack[-1])
        except StopIteration:
            stack.pop()
            continue
        if isinstance(item, (list, tuple)):
            stack.append(iter(item))
        else:
            result.append(item)
    return result

