    """Count islands in a binary-like grid.
    Accepts cells that are integers, booleans, or numeric strings.
    Handles empty and non‑rectangular grids.
    """
    if not grid:
        return 0
    rows = len(grid)
    # If all rows are empty, no islands.
    if all(len(row) == 0 for row in grid):
        return 0
    def is_land(val):
        # Returns True if the cell should be considered land (value 1).
        if isinstance(val, bool):
            return val
        if isinstance(val, (int, )):
            return val == 1
        if isinstance(val, str):
            return val.isdigit() and int(val) == 1
        return False
    visited = set()
    def dfs(r, c):
        stack = [(r, c)]
        while stack:
            x, y = stack.pop()
            if (x, y) in visited:
                continue
            visited.add((x, y))
            for dx, dy in ((1,0), (-1,0), (0,1), (0,-1)):
                nx, ny = x+dx, y+dy
                if 0 <= nx < rows and 0 <= ny < len(grid[nx]):
                    if is_land(grid[nx][ny]) and (nx, ny) not in visited:
                        stack.append((nx, ny))
    islands = 0
    for i in range(rows):
        for j in range(len(grid[i])):
            if is_land(grid[i][j]) and (i, j) not in visited:
                islands += 1
                dfs(i, j)
    return islands

