def solve(tokens):
    """Evaluate Reverse Polish Notation.
    Supports '+', '-', '*', '/' where division truncates toward zero.
    """
    stack = []
    for token in tokens:
        if token in '+-*/':
            b = stack.pop()
            a = stack.pop()
            if token == '+':
                res = a + b
            elif token == '-':
                res = a - b
            elif token == '*':
                res = a * b
            else:  # division
                if b == 0:
                    # undefined; return 0 as safe fallback
                    res = 0
                else:
                    # truncates toward zero
                    sign = -1 if (a < 0) ^ (b < 0) else 1
                    res = sign * (abs(a) // abs(b))
            stack.append(res)
        else:
            stack.append(int(token))
    return stack[-1] if stack else 0

