def solve(tokens):
    """Evaluate Reverse Polish Notation with safe division.
    Operators '+', '-', '*', '/' where division truncates toward zero.
    If division by zero occurs, returns 0 for that operation.
    """
    stack = []
    for token in tokens:
        if token in '+-*/':
            b = stack.pop()
            a = stack.pop()
            if token == '+':
                res = a + b
            elif token == '-':
                res = a - b
            elif token == '*':
                res = a * b
            else:  # division
                if b == 0:
                    res = 0
                else:
                    sign = -1 if (a < 0) ^ (b < 0) else 1
                    res = sign * (abs(a) // abs(b))
            stack.append(res)
        else:
            stack.append(int(token))
    return stack[-1] if stack else 0

