def solve(grid):
    """Count islands in a binary grid.
    The grid may be rectangular or jagged. Only cells with integer value 1 are land.
    Empty rows and completely empty grids are handled correctly.
    """
    # If grid is empty or contains no cells, return 0
    if not grid or all(len(row) == 0 for row in grid):
        return 0
    rows = len(grid)
    # visited mirrors each row's length (handles jagged rows)
    visited = [[False] * len(grid[r]) for r in range(rows)]
    def is_land(val):
        return isinstance(val, int) and val == 1
    def dfs(r, c):
        stack = [(r, c)]
        while stack:
            i, j = stack.pop()
            if i < 0 or i >= rows:
                continue
            if j < 0 or j >= len(grid[i]):
                continue
            if visited[i][j] or not is_land(grid[i][j]):
                continue
            visited[i][j] = True
            # four neighbours
            stack.append((i - 1, j))
            stack.append((i + 1, j))
            stack.append((i, j - 1))
            stack.append((i, j + 1))
    count = 0
    for i in range(rows):
        for j in range(len(grid[i])):
            if not visited[i][j] and is_land(grid[i][j]):
                dfs(i, j)
                count += 1
    return count

