def solve(path):
    """Simplify an absolute Unix-style path.
    The function resolves '.' and '..' components, collapses multiple slashes,
    and ensures the result does not end with a trailing slash (unless it is the root).
    """
    parts = []
    for segment in path.split('/'):
        if segment == '' or segment == '.':
            continue
        if segment == '..':
            if parts:
                parts.pop()
        else:
            parts.append(segment)
    simplified = '/' + '/'.join(parts)
    return simplified if simplified != '' else '/'

