def solve(matrix):
    """Return elements of the matrix in clockwise spiral order.
    Handles empty matrix and non‑rectangular rows by treating missing cells as absent.
    """
    if not matrix:
        return []
    # Determine dimensions; assume rectangular for proper spiral.
    top, bottom = 0, len(matrix) - 1
    left, right = 0, len(matrix[0]) - 1
    result = []
    while top <= bottom and left <= right:
        # top row
        for col in range(left, right + 1):
            result.append(matrix[top][col])
        top += 1
        # right column
        for row in range(top, bottom + 1):
            result.append(matrix[row][right])
        right -= 1
        if top <= bottom:
            # bottom row
            for col in range(right, left - 1, -1):
                result.append(matrix[bottom][col])
            bottom -= 1
        if left <= right:
            # left column
            for row in range(bottom, top - 1, -1):
                result.append(matrix[row][left])
            left += 1
    return result

def solve(n, b):
    """Convert integer n to a string representation in base b (2 <= b <= 36).
    Uses digits 0-9 then a-z. Handles negative numbers with a leading '-'.
    """
    if not (2 <= b <= 36):
        raise ValueError('Base must be between 2 and 36')
    if n == 0:
        return '0'
    digits = '0123456789abcdefghijklmnopqrstuvwxyz'
    sign = '-' if n < 0 else ''
    n = -n if n < 0 else n
    res = []
    while n > 0:
        n, rem = divmod(n, b)
        res.append(digits[rem])
    return sign + ''.join(reversed(res))

