def solve(nested):
    """Flatten a nested list of integers.
    The input may contain integers and lists (which themselves may contain
    integers or further lists) to arbitrary depth. Returns a flat list of the
    integers preserving the original order.
    """
    result = []
    def helper(item):
        if isinstance(item, list):
            for sub in item:
                helper(sub)
        else:
            # Only integers are expected; other types are ignored.
            if isinstance(item, int):
                result.append(item)
    helper(nested)
    return result

